'use client';

import { useEffect, useRef, useState } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import {
  pressedQuietOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { CalendarIcon, ListChecksIcon } from '@/registry/ndeko/lib/icons';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/registry/ndeko/ui/breadcrumb';
import { Chip } from '@/registry/ndeko/ui/chip';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Tabs, TabsList, TabsPanel, TabsTab } from '@/registry/ndeko/ui/tabs';

import { CondensedBar } from './condensed-bar';
import { MEMBERS, PROJECT, TABS, WORKSPACE, type TabId } from './data';
import { HeaderActions } from './header-actions';
import { ActivityPanel, FilesPanel, OverviewPanel, TasksPanel } from './panels';
import { INITIAL, LOOP_AFTER_MS, reducer, RESTING, SCRIPT } from './session';
import { TitleEditor } from './title-editor';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** The height of the bar: the title counts as gone once it has passed under it. */
const BAR_HEIGHT_PX = 48;

const COPIED_FOR_MS = 1600;

const PROJECT_LINK = 'https://morrow.example/projects/harbour-street';

const SHOWN_MEMBERS = 4;

const STATUS_LABELS = [PROJECT.status, 'Archived'];

const PANELS: Record<TabId, React.ReactNode> = {
  overview: <OverviewPanel />,
  tasks: <TasksPanel />,
  files: <FilesPanel />,
  activity: <ActivityPanel />,
};

function tabOf(value: unknown) {
  const tab = TABS.find((candidate) => candidate.id === value);
  return tab?.id;
}

function statusLabelOf(isArchived: boolean) {
  if (isArchived) {
    return 'Archived';
  }
  return PROJECT.status;
}

function statusColorOf(isArchived: boolean) {
  if (isArchived) {
    return 'var(--muted-foreground)';
  }
  return 'var(--success)';
}

function watchLineOf(isWatching: boolean) {
  if (isWatching) {
    return 'You are watching this project';
  }
  return 'You stopped watching this project';
}

function scrollBehaviorOf(shouldReduceMotion: boolean): ScrollBehavior {
  if (shouldReduceMotion) {
    return 'auto';
  }
  return 'smooth';
}

function archiveLineOf(isArchived: boolean) {
  if (isArchived) {
    return 'Project archived';
  }
  return 'Project restored';
}

export default function PageHeaders01() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
    takeOver,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const shouldReduceMotion = usePrefersReducedMotion();
  const frameRef = useRef<HTMLDivElement>(null);
  const rowRef = useRef<HTMLDivElement>(null);
  const [isCondensed, setIsCondensed] = useState(false);
  const [title, setTitle] = useState(PROJECT.title);
  const [isEditing, setIsEditing] = useState(false);
  const [isWatching, setIsWatching] = useState(false);
  const [isLinkCopied, setIsLinkCopied] = useState(false);
  const [isArchived, setIsArchived] = useState(false);
  const [spoken, setSpoken] = useState('');
  const progress = PROJECT.tasksDone / PROJECT.tasksTotal;
  const percent = Math.round(progress * 100);
  const progressStyle = { transform: `scaleX(${progress})` };
  const statusLabel = statusLabelOf(isArchived);
  const statusColor = statusColorOf(isArchived);
  const otherMembers = MEMBERS.length - SHOWN_MEMBERS;
  const shownMembers = MEMBERS.slice(0, SHOWN_MEMBERS);
  const message = spokenUnless(isAutoplaying, spoken);
  const canReplay = isFinished && !isAutoplaying;

  useEffect(() => {
    if (state.scrollRequest === 0) {
      return;
    }
    frameRef.current?.scrollTo({ top: state.scrollTop, behavior: 'smooth' });
  }, [state.scrollRequest, state.scrollTop]);

  useEffect(() => {
    const frame = frameRef.current;
    const row = rowRef.current;
    if (!frame || !row) {
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries.at(-1);
        if (!entry) {
          return;
        }
        const rootTop = entry.rootBounds?.top ?? 0;
        const isAbove = entry.boundingClientRect.top < rootTop;
        setIsCondensed(!entry.isIntersecting && isAbove);
      },
      {
        root: frame,
        rootMargin: `-${BAR_HEIGHT_PX}px 0px 0px 0px`,
        threshold: 0,
      }
    );
    observer.observe(row);
    return () => observer.disconnect();
  }, []);

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  /** A wheel or a trackpad scrolling the frame is a person reading: the demonstration stops for good. */
  function yieldToWheel() {
    if (isAutoplaying) {
      takeOver();
    }
  }

  function pickTab(value: unknown) {
    const tab = tabOf(value);
    if (tab) {
      act({ type: 'tabPicked', tab });
    }
  }

  function startEditing() {
    const behavior = scrollBehaviorOf(shouldReduceMotion);
    frameRef.current?.scrollTo({ top: 0, behavior });
    setIsEditing(true);
  }

  function leaveEditing() {
    setIsEditing(false);
    focusLater('[data-action="edit"], [data-action="more"]');
  }

  function saveTitle(next: string) {
    setTitle(next);
    setSpoken(`Project renamed to ${next}`);
    leaveEditing();
  }

  async function share() {
    try {
      await navigator.clipboard.writeText(PROJECT_LINK);
    } catch {
      setSpoken('The link could not be copied');
      return;
    }
    setIsLinkCopied(true);
    setSpoken('Link to the project copied');
    schedule(() => setIsLinkCopied(false), COPIED_FOR_MS);
  }

  function toggleWatching() {
    const next = !isWatching;
    setIsWatching(next);
    const line = watchLineOf(next);
    setSpoken(line);
  }

  function toggleArchived() {
    const next = !isArchived;
    setIsArchived(next);
    const line = archiveLineOf(next);
    setSpoken(line);
  }

  function replay() {
    frameRef.current?.scrollTo({ top: 0 });
    restart();
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container relative flex h-dvh min-h-[36rem] w-full flex-col overflow-hidden'
      >
        <div
          ref={frameRef}
          onWheel={yieldToWheel}
          className='relative min-h-0 flex-1 overflow-y-auto overscroll-contain'
        >
          <div className='sticky top-0 z-20 h-0'>
            <CondensedBar
              isShown={isCondensed}
              title={title}
              statusLabel={statusLabel}
              statusColor={statusColor}
              progress={progress}
              onEdit={startEditing}
            />
          </div>

          <div className='mx-auto flex max-w-5xl flex-col gap-6 px-4 pt-5 pb-16 @2xl:px-8 @2xl:pt-8'>
            <header className='flex flex-col gap-4'>
              <div className='flex min-h-7 items-center gap-3'>
                <Breadcrumb className='min-w-0 flex-1'>
                  <BreadcrumbList>
                    <BreadcrumbItem>
                      <BreadcrumbLink
                        href={WORKSPACE.href}
                        className='flex items-center gap-1.5'
                      >
                        <CompanyMark seed={WORKSPACE.name} size='sm' />
                        {WORKSPACE.name}
                      </BreadcrumbLink>
                    </BreadcrumbItem>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem>
                      <BreadcrumbLink href={WORKSPACE.projectsHref}>
                        Projects
                      </BreadcrumbLink>
                    </BreadcrumbItem>
                    <BreadcrumbSeparator />
                    <BreadcrumbItem className='min-w-0'>
                      <BreadcrumbPage className='truncate'>
                        {title}
                      </BreadcrumbPage>
                    </BreadcrumbItem>
                  </BreadcrumbList>
                </Breadcrumb>
                <ReplayButton
                  isShown={canReplay}
                  onReplay={replay}
                  label='Replay'
                />
              </div>

              <div ref={rowRef} className='relative flex items-start gap-3'>
                {isEditing && (
                  <TitleEditor
                    title={title}
                    onSave={saveTitle}
                    onCancel={leaveEditing}
                  />
                )}
                {!isEditing && (
                  <div className='flex min-w-0 flex-1 flex-wrap items-center gap-x-3 gap-y-2'>
                    <h1 className='text-2xl font-semibold text-balance @sm:text-3xl'>
                      {title}
                    </h1>
                    <Chip color={statusColor}>
                      <WordRoll text={statusLabel} labels={STATUS_LABELS} />
                    </Chip>
                  </div>
                )}
                {!isEditing && (
                  <HeaderActions
                    rowRef={rowRef}
                    isWatching={isWatching}
                    isLinkCopied={isLinkCopied}
                    isArchived={isArchived}
                    onEdit={startEditing}
                    onShare={share}
                    onWatch={toggleWatching}
                    onArchive={toggleArchived}
                  />
                )}
              </div>

              <ul className='text-muted-foreground flex flex-wrap items-center gap-x-5 gap-y-2 text-[13px]'>
                <li className='flex items-center gap-2'>
                  <Avatar seed={PROJECT.lead} className='size-5' />
                  <span>
                    <span className='text-foreground'>{PROJECT.lead}</span>{' '}
                    leads
                  </span>
                </li>
                <li className='flex items-center gap-1.5'>
                  <CalendarIcon className='size-4' />
                  {PROJECT.due}
                </li>
                <li className='flex items-center gap-1.5 tabular-nums'>
                  <ListChecksIcon className='size-4' />
                  {PROJECT.tasksDone} of {PROJECT.tasksTotal} tasks done
                </li>
                <li className='flex items-center gap-2'>
                  <span className='flex -space-x-1.5' aria-hidden='true'>
                    {shownMembers.map((member) => (
                      <Avatar
                        key={member.name}
                        seed={member.name}
                        className='ring-background size-5 ring-2'
                      />
                    ))}
                  </span>
                  <span className='tabular-nums'>
                    {MEMBERS.length} members
                    <span className='sr-only'>, {otherMembers} not shown</span>
                  </span>
                </li>
              </ul>

              <div className='flex items-center gap-3'>
                <div
                  role='progressbar'
                  aria-label='Tasks done'
                  aria-valuemin={0}
                  aria-valuemax={PROJECT.tasksTotal}
                  aria-valuenow={PROJECT.tasksDone}
                  className='bg-foreground/10 h-1.5 flex-1 overflow-hidden rounded-full'
                >
                  <div
                    style={progressStyle}
                    className='bg-primary h-full w-full origin-left rounded-full'
                  />
                </div>
                <span className='text-muted-foreground w-9 text-end text-xs tabular-nums'>
                  {percent}%
                </span>
              </div>
            </header>

            <Tabs value={state.tab} onValueChange={pickTab} className='gap-6'>
              <div className='relative -mx-4 overflow-x-auto px-4 @2xl:mx-0 @2xl:px-0'>
                <TabsList>
                  {TABS.map((tab) => (
                    <TabsTab
                      key={tab.id}
                      value={tab.id}
                      className={pressedQuietOf(pressed === `tab-${tab.id}`)}
                    >
                      {tab.label}
                      {tab.count !== undefined && (
                        <span className='text-muted-foreground text-xs tabular-nums'>
                          {tab.count}
                        </span>
                      )}
                    </TabsTab>
                  ))}
                </TabsList>
              </div>
              {TABS.map((tab) => (
                <TabsPanel key={tab.id} value={tab.id}>
                  {PANELS[tab.id]}
                </TabsPanel>
              ))}
            </Tabs>
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

import { PencilIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Chip } from '@/registry/ndeko/ui/chip';

const SHOWN = 'translate-y-0 opacity-100';

const HIDDEN = '-translate-y-full opacity-0';

function placeOf(isShown: boolean) {
  if (isShown) {
    return SHOWN;
  }
  return HIDDEN;
}

function hiddenOf(isShown: boolean) {
  if (isShown) {
    return undefined;
  }
  return true;
}

type CondensedBarProps = {
  isShown: boolean;
  title: string;
  statusLabel: string;
  statusColor: string;
  progress: number;
  onEdit: () => void;
};

export function CondensedBar({
  isShown,
  title,
  statusLabel,
  statusColor,
  progress,
  onEdit,
}: CondensedBarProps) {
  const progressStyle = { transform: `scaleX(${progress})` };

  return (
    <div
      inert={!isShown}
      aria-hidden={hiddenOf(isShown)}
      className={cn(
        'bg-background hairline-b border-border absolute inset-x-0 top-0 transition-[translate,opacity] duration-200 ease-(--ease-out-strong)',
        placeOf(isShown)
      )}
    >
      <div className='mx-auto flex h-12 max-w-5xl items-center gap-3 px-4 @2xl:px-8'>
        <p className='min-w-0 truncate text-sm font-semibold'>{title}</p>
        <Chip color={statusColor}>{statusLabel}</Chip>
        <span className='flex-1' />
        <Button type='button' size='sm' onClick={onEdit}>
          <PencilIcon />
          Edit
        </Button>
      </div>
      <span
        aria-hidden='true'
        style={progressStyle}
        className='bg-primary absolute inset-x-0 bottom-0 h-0.5 origin-left'
      />
    </div>
  );
}

'use client';

import { useLayoutEffect, useRef, useState, type RefObject } from 'react';

import {
  ArchiveIcon,
  ArchiveRestoreIcon,
  CheckIcon,
  EllipsisIcon,
  EyeIcon,
  PencilIcon,
  Share2Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';

type ActionId = 'edit' | 'share' | 'watch';

/** Edit stays in the row the longest, Watch folds first. */
const BY_PRIORITY: ActionId[] = ['edit', 'share', 'watch'];

/** In the row the primary action sits at the end, next to More. */
const ROW_ORDER: ActionId[] = ['watch', 'share', 'edit'];

/** The title keeps at least this much of the row before an action gives way. */
const TITLE_MIN_PX = 160;

const ROW_GAP_PX = 12;

const ACTION_GAP_PX = 8;

function widthOf(measure: HTMLElement, key: string) {
  const element = measure.querySelector<HTMLElement>(`[data-measure="${key}"]`);
  return element?.offsetWidth ?? 0;
}

function countThatFits(measure: HTMLElement, budget: number) {
  let used = widthOf(measure, 'more');
  let count = 0;
  for (const id of BY_PRIORITY) {
    const next = used + ACTION_GAP_PX + widthOf(measure, id);
    if (next > budget) {
      break;
    }
    used = next;
    count += 1;
  }
  return count;
}

function watchLabelOf(isWatching: boolean) {
  if (isWatching) {
    return 'Watching';
  }
  return 'Watch';
}

export type HeaderActionsProps = {
  /** The row the title shares with the actions: its width decides how many actions stay out. */
  rowRef: RefObject<HTMLDivElement | null>;
  isWatching: boolean;
  isLinkCopied: boolean;
  isArchived: boolean;
  onEdit: () => void;
  onShare: () => void;
  onWatch: () => void;
  onArchive: () => void;
};

export function HeaderActions({
  rowRef,
  isWatching,
  isLinkCopied,
  isArchived,
  onEdit,
  onShare,
  onWatch,
  onArchive,
}: HeaderActionsProps) {
  const measureRef = useRef<HTMLDivElement>(null);
  const [visibleCount, setVisibleCount] = useState(BY_PRIORITY.length);
  const [isMeasured, setIsMeasured] = useState(false);
  const shown = BY_PRIORITY.slice(0, visibleCount);
  const folded = BY_PRIORITY.slice(visibleCount);
  const inRow = ROW_ORDER.filter((id) => shown.includes(id));
  const watchLabel = watchLabelOf(isWatching);

  useLayoutEffect(() => {
    const row = rowRef.current;
    const measure = measureRef.current;
    if (!row || !measure) {
      return;
    }
    function fit() {
      if (!row || !measure) {
        return;
      }
      const budget = row.clientWidth - TITLE_MIN_PX - ROW_GAP_PX;
      const count = countThatFits(measure, budget);
      setVisibleCount(count);
      setIsMeasured(true);
    }
    const observer = new ResizeObserver(fit);
    observer.observe(row);
    observer.observe(measure);
    return () => observer.disconnect();
  }, [rowRef]);

  const glyphs: Record<ActionId, React.ReactNode> = {
    edit: <PencilIcon />,
    share: (
      <Swap swapKey={String(isLinkCopied)}>
        {isLinkCopied && <CheckIcon />}
        {!isLinkCopied && <Share2Icon />}
      </Swap>
    ),
    watch: (
      <Swap swapKey={String(isWatching)}>
        {isWatching && <CheckIcon />}
        {!isWatching && <EyeIcon />}
      </Swap>
    ),
  };

  const labels: Record<ActionId, string> = {
    edit: 'Edit',
    share: 'Share',
    watch: watchLabel,
  };

  const handlers: Record<ActionId, () => void> = {
    edit: onEdit,
    share: onShare,
    watch: onWatch,
  };

  return (
    <>
      <div
        className={cn(
          'flex shrink-0 items-center gap-2 transition-opacity duration-150',
          !isMeasured && 'opacity-0'
        )}
      >
        {inRow.map((id) => {
          const isPrimary = id === 'edit';
          let variant: 'default' | 'outline' = 'outline';
          if (isPrimary) {
            variant = 'default';
          }
          return (
            <Button
              key={id}
              type='button'
              variant={variant}
              data-action={id}
              onClick={handlers[id]}
            >
              {glyphs[id]}
              {labels[id]}
            </Button>
          );
        })}
        <DropdownMenu>
          <DropdownMenuTrigger
            render={
              <Button
                type='button'
                variant='outline'
                size='icon'
                data-action='more'
                aria-label='More actions'
              />
            }
          >
            <EllipsisIcon />
          </DropdownMenuTrigger>
          <DropdownMenuContent align='end' className='min-w-48'>
            {folded.map((id) => (
              <DropdownMenuItem key={id} onClick={handlers[id]}>
                {glyphs[id]}
                {labels[id]}
              </DropdownMenuItem>
            ))}
            {folded.length > 0 && <DropdownMenuSeparator />}
            {!isArchived && (
              <DropdownMenuItem variant='destructive' onClick={onArchive}>
                <ArchiveIcon />
                Archive project
              </DropdownMenuItem>
            )}
            {isArchived && (
              <DropdownMenuItem onClick={onArchive}>
                <ArchiveRestoreIcon />
                Restore project
              </DropdownMenuItem>
            )}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
      <div
        aria-hidden='true'
        className='pointer-events-none absolute top-0 left-0 h-0 w-0 overflow-hidden'
      >
        <div ref={measureRef} inert className='invisible flex w-max gap-2'>
          <Button type='button' tabIndex={-1} data-measure='edit'>
            <PencilIcon />
            Edit
          </Button>
          <Button
            type='button'
            variant='outline'
            tabIndex={-1}
            data-measure='share'
          >
            <Share2Icon />
            Share
          </Button>
          <Button
            type='button'
            variant='outline'
            tabIndex={-1}
            data-measure='watch'
          >
            <EyeIcon />
            Watching
          </Button>
          <Button
            type='button'
            variant='outline'
            size='icon'
            tabIndex={-1}
            data-measure='more'
            aria-label='More actions'
          >
            <EllipsisIcon />
          </Button>
        </div>
      </div>
    </>
  );
}

'use client';

import { useEffect, useId, useRef, useState } from 'react';

import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';

type TitleEditorProps = {
  title: string;
  onSave: (title: string) => void;
  onCancel: () => void;
};

export function TitleEditor({ title, onSave, onCancel }: TitleEditorProps) {
  const [draft, setDraft] = useState(title);
  const inputRef = useRef<HTMLInputElement>(null);
  const fieldId = useId();
  const trimmed = draft.trim();
  const canSave = trimmed !== '';

  useEffect(() => {
    const input = inputRef.current;
    input?.focus({ preventScroll: true });
    input?.select();
  }, []);

  function save(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!canSave) {
      return;
    }
    onSave(trimmed);
  }

  function cancelOnEscape(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    event.preventDefault();
    onCancel();
  }

  return (
    <form
      onSubmit={save}
      className='flex min-w-0 flex-1 flex-wrap items-center gap-2 transition-opacity duration-150 starting:opacity-0'
    >
      <label htmlFor={fieldId} className='sr-only'>
        Project name
      </label>
      <Input
        ref={inputRef}
        id={fieldId}
        size='lg'
        autoComplete='off'
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={cancelOnEscape}
        className='min-w-[12rem] flex-1 font-semibold'
      />
      <div className='flex items-center gap-2'>
        <Button type='submit' disabled={!canSave}>
          Save
        </Button>
        <Button type='button' variant='ghost' onClick={onCancel}>
          Cancel
        </Button>
      </div>
    </form>
  );
}

import {
  CheckIcon,
  CircleDashedIcon,
  CircleIcon,
  FileSpreadsheetIcon,
  FileTextIcon,
  LayersIcon,
  LoaderCircleIcon,
  type Icon,
} from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Chip } from '@/registry/ndeko/ui/chip';

import {
  ACTIVITY,
  FILES,
  MEMBERS,
  MILESTONES,
  PROJECT,
  TASKS,
  type ActivityItem,
  type MilestoneState,
  type ProjectFile,
  type TaskState,
} from './data';

const SECTION_TITLE = 'text-[13px] font-medium';

const SURFACE =
  'bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]';

const MILESTONE_GLYPH: Record<MilestoneState, React.ReactNode> = {
  done: <CheckIcon className='text-success-foreground size-3.5' />,
  current: <span className='bg-primary size-2 rounded-full' />,
  upcoming: <CircleDashedIcon className='text-muted-foreground size-3.5' />,
};

const MILESTONE_TRAY: Record<MilestoneState, string> = {
  done: 'bg-success/10',
  current: 'bg-primary/10',
